package com.tencent.weknora.model.client;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.io.IOException;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.function.Consumer;

/** Production local Ollama NDJSON chat; complete tool objects and Go event semantics. */
public final class OllamaChat implements ChatModel {
    private static final ObjectMapper JSON=SafeModelHttp.JSON;private final OllamaRuntime runtime;private final ModelEndpoint endpoint;
    public OllamaChat(OllamaRuntime runtime,ModelEndpoint endpoint){this.runtime=runtime;this.endpoint=endpoint;}
    @Override public String modelId(){return endpoint.id;}@Override public String modelName(){return endpoint.name;}
    public ObjectNode request(CallContext call,List<ObjectNode> messages,ObjectNode opts,boolean stream){ObjectNode out=JSON.createObjectNode().put("model",endpoint.name).put("stream",stream);ArrayNode turns=JSON.createArrayNode();for(ObjectNode m:messages){String content=ModelText.neutralize(m.path("content").asText());ObjectNode turn=JSON.createObjectNode().put("role",m.path("role").asText());List<String> images=new ArrayList<>();m.path("images").forEach(v->images.add(v.asText()));StringBuilder text=new StringBuilder();for(JsonNode part:m.path("multi_content")){if(part.path("type").asText().equals("text"))text.append(ModelText.neutralize(part.path("text").asText()));else if(part.path("type").asText().equals("image_url")&&!part.path("image_url").path("url").asText().isEmpty())images.add(part.path("image_url").path("url").asText());}if(content.isEmpty())content=text.toString();turn.put("content",content);if(m.path("role").asText().equals("tool")&&!m.path("name").asText().isEmpty())turn.put("tool_name",m.path("name").asText());ArrayNode toolCalls=JSON.createArrayNode();for(JsonNode tc:m.path("tool_calls")){long index=0;try{String id=tc.path("id").asText();if(id.matches("[+-]?[0-9]+"))index=Long.parseLong(id);}catch(NumberFormatException ignored){}JsonNode arguments=JSON.createObjectNode();if(!tc.path("function").path("arguments").asText().isEmpty())arguments=OllamaTypedJson.toolArguments(ModelText.neutralize(tc.path("function").path("arguments").asText()));toolCalls.add(JSON.createObjectNode().set("function",JSON.createObjectNode().put("index",index).put("name",tc.path("function").path("name").asText()).set("arguments",arguments)));}if(!toolCalls.isEmpty())turn.set("tool_calls",toolCalls);
            if(m.path("role").asText().equals("user")){ArrayNode bytes=JSON.createArrayNode();for(String image:images){byte[] data=image(call,image);if(data!=null)bytes.add(Base64.getEncoder().encodeToString(data));}if(!bytes.isEmpty())turn.set("images",bytes);}turns.add(turn);
        }out.set("messages",turns);ObjectNode options=JSON.createObjectNode();if(opts!=null){options.put("temperature",opts.path("temperature").asDouble());if(opts.path("top_p").asDouble()>0)options.set("top_p",opts.get("top_p"));long budget=opts.path("max_completion_tokens").asLong();if(budget<=0)budget=opts.path("max_tokens").asLong();if(budget>0)options.put("num_predict",budget);String level=opts.path("reasoning_effort").asText();boolean requested=!level.isEmpty()&&Set.of("off","auto","minimal","low","medium","high","xhigh","max","none","false","disabled","true","enabled","default","on").contains(level);if(requested)out.put("think",!Set.of("off","none","false","disabled").contains(level));else if(opts.hasNonNull("thinking"))out.put("think",opts.path("thinking").asBoolean());if(opts.has("format"))out.set("format",opts.get("format").deepCopy());ArrayNode tools=JSON.createArrayNode();for(JsonNode t:opts.path("tools")){JsonNode fn=t.path("function");ObjectNode f=JSON.createObjectNode().put("name",fn.path("name").asText());if(!fn.path("description").asText().isEmpty())f.put("description",fn.path("description").asText());f.set("parameters",parameters(fn.path("parameters"),false));tools.add(JSON.createObjectNode().put("type",t.path("type").asText()).set("function",f));}if(!tools.isEmpty())out.set("tools",tools);}out.set("options",options);return out;
    }
    private byte[] image(CallContext call,String ref){if(ref.startsWith("data:")){int at=ref.indexOf(";base64,");if(at<0)return null;String b64=ref.substring(at+8).replace("\r","").replace("\n","");try{if(b64.length()%4!=0)return null;return Base64.getDecoder().decode(b64);}catch(IllegalArgumentException ex){return null;}}if(ref.startsWith("resource://")||ref.startsWith("local://")||ref.startsWith("storage://"))throw new ModelClientException("Native Ollama storage-backed image resolution is not migrated");if(ref.startsWith("http://")||ref.startsWith("https://"))try(var response=runtime.http.get(call,ref,Map.of(),Duration.ofSeconds(30))){return response.body().readNBytes(20*1024*1024);}catch(ModelClientException|IOException ex){call.check();return null;}return null;}
    private static ObjectNode parameters(JsonNode input,boolean property){ObjectNode out=JSON.createObjectNode();JsonNode type=input.path("type");if(property){if(type.isTextual()&&!type.asText().isEmpty())out.set("type",type);else if(type.isArray()&&!type.isEmpty())out.set("type",type.size()==1?type.get(0):type.deepCopy());}else out.put("type",type.isTextual()?type.asText():"");for(String key:List.of("$defs","items","enum","required","description")){JsonNode value=input.path(key);if(!value.isMissingNode()&&!value.isNull()&&(!value.isContainerNode()||!value.isEmpty())&&(!value.isTextual()||!value.asText().isEmpty())&&(!property||!key.equals("$defs"))&&(property||!Set.of("enum","description").contains(key)))out.set(key,value.deepCopy());}JsonNode properties=input.path("properties");if(properties.isObject()){ObjectNode p=JSON.createObjectNode();properties.fields().forEachRemaining(e->p.set(e.getKey(),parameters(e.getValue(),true)));out.set("properties",p);}else if(!property)out.putNull("properties");if(property&&input.path("anyOf").isArray()&&!input.path("anyOf").isEmpty()){ArrayNode array=JSON.createArrayNode();input.path("anyOf").forEach(n->array.add(parameters(n,true)));out.set("anyOf",array);}return out;}
    private static ArrayNode calls(JsonNode n){ArrayNode calls=JSON.createArrayNode();for(JsonNode call:n.path("message").path("tool_calls")){JsonNode f=call.path("function");calls.add(JSON.createObjectNode().put("id",Long.toString(f.path("index").asLong())).put("type","function").set("function",JSON.createObjectNode().put("name",f.path("name").asText()).put("arguments",OllamaJson.arguments(f.path("arguments")))));}return calls;}
    private static ObjectNode usage(long prompt,long completion){return JSON.createObjectNode().put("prompt_tokens",prompt).put("completion_tokens",completion).put("total_tokens",prompt+completion).put("cache_reported",false).put("cache_status","unsupported");}
    @Override public ObjectNode chat(CallContext call,List<ObjectNode> messages,ObjectNode opts){runtime.ensure(call,endpoint.name);ObjectNode result=JSON.createObjectNode().put("content","");result.set("usage",usage(0,0));try{runtime.chat(call,request(call,messages,opts,false),n->{OllamaJson.validateChat(n);String content=n.path("message").path("content").asText();if(content.isEmpty())content=n.path("message").path("thinking").asText();result.put("content",content);ArrayNode calls=calls(n);if(calls.isEmpty())result.remove("tool_calls");else result.set("tool_calls",calls);if(n.path("eval_count").asLong()>0)result.set("usage",usage(n.path("prompt_eval_count").asLong(),n.path("eval_count").asLong()));});return result;}catch(ModelClientException ex){throw new ModelClientException(endpoint.safe("聊天请求失败: "+ex.getMessage()));}}
    private static ObjectNode event(String kind,String text,boolean done){return JSON.createObjectNode().put("id","").put("response_type",kind).put("content",text).put("done",done);}
    private void emit(CallContext call,Consumer<ObjectNode> consumer,ObjectNode event){call.check();consumer.accept(event);call.check();}
    @Override public void stream(CallContext call,List<ObjectNode> messages,ObjectNode opts,Consumer<ObjectNode> consumer){runtime.ensure(call,endpoint.name);ObjectNode request=request(call,messages,opts,true);boolean[] thinking={false};try{runtime.chat(call,request,n->{OllamaJson.validateChat(n);String thought=n.path("message").path("thinking").asText(),answer=n.path("message").path("content").asText();if(!thought.isEmpty()){thinking[0]=true;emit(call,consumer,event("thinking",thought,false));}if(!answer.isEmpty()){if(thinking[0]){thinking[0]=false;emit(call,consumer,event("thinking","",true));}emit(call,consumer,event("answer",answer,false));}ArrayNode calls=calls(n);if(!calls.isEmpty()){emit(call,consumer,event("tool_call","",false).set("tool_calls",calls));for(JsonNode tool:n.path("message").path("tool_calls")){JsonNode fn=tool.path("function");if(fn.path("name").asText().equals("thinking")&&fn.path("arguments").path("thought").isTextual()&&!fn.path("arguments").path("thought").asText().isEmpty())emit(call,consumer,event("thinking",fn.path("arguments").path("thought").asText(),false).set("data",JSON.createObjectNode().put("source","thinking_tool").put("tool_call_id",Long.toString(fn.path("index").asLong()))));}}if(n.path("done").asBoolean()){ObjectNode end=event("answer","",true);long prompt=n.path("prompt_eval_count").asLong(),completion=n.path("eval_count").asLong();if(prompt>0||completion>0)end.set("usage",usage(prompt,completion));emit(call,consumer,end);}});}catch(CancellationException ex){throw ex;}catch(ModelClientException ex){call.check();emit(call,consumer,event("error",endpoint.safe(ex.getMessage()),true));}}
}
